WITH flagged AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_session FROM payments), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT s.id, s.order_id, s.method, s.amount, s.status, s.is_new_session, CASE WHEN status RLIKE '^(REFUNDED|FAILED)$' THEN 'GROUP_A' ELSE 'GROUP_B' END AS status_zone, (SELECT AVG(x.cost) FROM shipments x WHERE x.order_id = s.order_id) AS avg_shipment_cost FROM islands s ORDER BY method NULLS LAST;
